package com.meditrace.blockchain;

import java.time.Instant;

/**
 * A unit of work placed on the {@link Miner}'s queue: "seal supply-chain transaction
 * {@code txId} into a new block".
 * <p>
 * Declared as a Java record - an immutable data carrier whose constructor, accessors,
 * {@code equals}, {@code hashCode} and {@code toString} are generated by the compiler.
 *
 * @param txId     primary key of the row in the {@code transactions} table
 * @param queuedAt when the task was submitted (used for logging)
 */
public record MiningTask(long txId, Instant queuedAt) {

    /** Convenience factory stamping the current time. */
    public static MiningTask of(long txId) {
        return new MiningTask(txId, Instant.now());
    }
}
